var Welcome={init(){const root=$('#welcomeScreen'),enter=$('#enterStudio');if(document.documentElement.dataset.welcome==='closed'){root.classList.add('hidden');return}enter.onclick=()=>{try{sessionStorage.setItem('sams-canvas.entered','1')}catch{}document.documentElement.dataset.welcome='closed';root.classList.add('leaving');setTimeout(()=>root.classList.add('hidden'),240);requestAnimationFrame(()=>{updateTabs();if(tab==='whiteboard')updateTransform()})};requestAnimationFrame(()=>enter.focus({preventScroll:true}))}};
